begin;
select plan(25);
select is((select count(*)::integer from private.part_four_scientific_authority where claim_id ~ '^G0[1-5]-'),0,'No actual scientific admission seeded');
select ok(not has_table_privilege('authenticated','private.part_four_scientific_authority','SELECT,INSERT,UPDATE,DELETE'),'Client cannot admit science');
select ok(not has_table_privilege('anon','private.part_four_historical_releases','SELECT,INSERT,UPDATE,DELETE'),'Anon cannot choose history');
select ok(not has_function_privilege('authenticated','private.part_four_science_field_allowed(jsonb,timestamptz,text)','EXECUTE'),'Client cannot override science rights');
create temporary table science_fixture(f jsonb);
insert into private.part_four_scientific_authority values(repeat('a',64),repeat('b',64),'synthetic-original','fixture-reviewer','fixture-qualification',array['fixture-source'],'[{"id":"fixture-source","url":"https://fixture.invalid/science","locator":"original synthetic proposition","retrievedAt":"2026-10-04","bodySha256":null,"reviewedAt":"2026-10-04T00:00:00Z"}]','fixture-grant','1','reference','Original synthetic reference.',null,'["Local fixture only."]',now()+interval '1 hour',true,true,true,false,false);
insert into science_fixture select jsonb_build_object('kind','scientific_claim','state','retained','sourceIds',jsonb_build_array('fixture-source'),'grants',jsonb_build_array(jsonb_build_object('field','science','sourceId','fixture-source','policyId','fixture-grant','policyVersion','1','validUntil',to_char(now()+interval '30 minutes','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'revoked',false,'operations',jsonb_build_object('process',true,'store',true,'display',true,'export',false))),'value',jsonb_build_object('manifestHash',repeat('a',64),'goal',null,'assessment',jsonb_build_object('claimHash',repeat('b',64),'claimId','synthetic-original','state','reference','admissionId','fixture-reviewer','reason','Original synthetic reference.','action',null,'reasons',jsonb_build_array('Local fixture only.'),'validUntil',to_char(now()+interval '30 minutes','YYYY-MM-DD"T"HH24:MI:SS"Z"')),'sources',jsonb_build_array((select source_metadata->0 from private.part_four_scientific_authority where claim_id='synthetic-original')||jsonb_build_object('validUntil',to_char(now()+interval '30 minutes','YYYY-MM-DD"T"HH24:MI:SS"Z"')))));
select ok(private.part_four_science_field_allowed(f,now()),'Exact synthetic reference and rights admitted') from science_fixture;
select ok(not private.part_four_science_field_allowed(f,now(),'export'),'Independent export restriction') from science_fixture;
select ok(not private.part_four_science_field_allowed(jsonb_set(f,'{value,assessment,reason}','"Changed unreviewed copy"'),now()),'Changed copy refused') from science_fixture;
select ok(not private.part_four_science_field_allowed(jsonb_set(f,'{value,sources,0,url}','"https://fixture.invalid/other"'),now()),'Changed source metadata refused') from science_fixture;
select ok(not private.part_four_science_field_allowed(jsonb_set(f,'{value,manifestHash}',to_jsonb(repeat('c',64))),now()),'Different manifest refused') from science_fixture;
select ok(not private.part_four_science_field_allowed(jsonb_set(f,'{grants}','[]'),now()),'Missing copied grants refused') from science_fixture;
select ok(not private.part_four_science_field_allowed(jsonb_set(f,'{value,sources,0,validUntil}',to_jsonb('2000-01-01T00:00:00Z'::text)),now()),'Expired source reference refused') from science_fixture;
select ok(not private.part_four_science_field_allowed(f,now()+interval '2 hours'),'Expired authority refused') from science_fixture;
-- Original synthetic two-goal packet: no actual claim or review is admitted.
update private.part_four_scientific_authority set allowed_state='supported' where claim_id='synthetic-original';
update science_fixture set f=f||jsonb_build_object('recordId',repeat('1',64),'withdrawalIds',jsonb_build_array('fixture-source','fixture-grant','1'),'originallyVisible',true,'reason',null);
update science_fixture set f=jsonb_set(f,'{value,assessment}',f->'value'->'assessment'||jsonb_build_object('family','G01','state','supported','missingFields','[]'::jsonb,'factIds','[]'::jsonb,'contextRevisionIds','[]'::jsonb,'sourceIds',jsonb_build_array('fixture-source')));
update science_fixture set f=jsonb_set(f,'{grants,0,retention}',jsonb_build_object('mode','retain_until','until',f->'grants'->0->'validUntil'));
update science_fixture set f=jsonb_set(f,'{value,goal}','"oiliness"');
insert into private.part_four_scientific_authority select manifest_hash,repeat('c',64),'synthetic-secondary',reviewer_id,qualification_ref,array['secondary-source'],jsonb_set(source_metadata,'{0,id}','"secondary-source"'),grant_id,grant_version,allowed_state,reason,action,qualifications,valid_until,process,store,display,export,revoked from private.part_four_scientific_authority where claim_id='synthetic-original';
create temporary table secondary_fixture as select jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(f,'{recordId}',to_jsonb(repeat('2',64))),'{value,assessment,claimHash}',to_jsonb(repeat('c',64))),'{value,assessment,claimId}','"synthetic-secondary"'),'{value,goal}','"fine_lines"'),'{sourceIds}','["secondary-source"]'),'{grants,0,sourceId}','"secondary-source"'),'{value,sources,0,id}','"secondary-source"') f from science_fixture;
update secondary_fixture set f=jsonb_set(jsonb_set(f,'{value,assessment,sourceIds}','["secondary-source"]'),'{withdrawalIds}','["secondary-source","fixture-grant","1"]');
create temporary table goal_packet as select jsonb_build_object('summary',jsonb_build_object('judgment','worth_considering','primaryFindingId','scientific:synthetic-original:oiliness','affirmativePremiseIds',jsonb_build_array('scientific:synthetic-original:oiliness','scientific:synthetic-secondary:fine_lines'),'overridingFindingIds','[]'::jsonb,'materialGapIds','[]'::jsonb),'findings',jsonb_build_array(jsonb_build_object('id','scientific:synthetic-original:oiliness','scientificEvidence',jsonb_build_object('claimHash',repeat('b',64))),jsonb_build_object('id','scientific:synthetic-secondary:fine_lines','scientificEvidence',jsonb_build_object('claimHash',repeat('c',64)))),'materialGaps','[]'::jsonb,'selectedTradeoffId',null,'partFour',jsonb_build_object('decisionState','supported','action','Synthetic original decision.','insights','[]'::jsonb,'scientificDecision',jsonb_build_object('manifestHash',repeat('a',64),'assessments',jsonb_build_array(jsonb_build_object('goal','oiliness','assessment',f->'value'->'assessment'),jsonb_build_object('goal','fine_lines','assessment',(select f->'value'->'assessment' from secondary_fixture))),'sourceRefs',(f->'value'->'sources')||(select f->'value'->'sources' from secondary_fixture),'unresolvedGoals','[]'::jsonb),'retainedEvidence',jsonb_build_object('version','part-four-retained-evidence/v1','savedAt',to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"'),'projectedAt',to_char(now(),'YYYY-MM-DD"T"HH24:MI:SS"Z"'),'purpose','retain','state','complete','fields',jsonb_build_array(f,(select f from secondary_fixture))))) p from science_fixture;
select ok(private.part_four_retained_evidence_valid(p->'partFour'->'retainedEvidence'),'two-goal synthetic retained fixture meets real whitelist') from goal_packet;
create temporary table same_claim_goal as select jsonb_set(jsonb_set(jsonb_set(f,'{recordId}',to_jsonb(repeat('3',64))),'{value,goal}','"fine_lines"'),'{withdrawalIds}','["fixture-source","fixture-grant","1","secondary-goal-context"]') f from science_fixture;
create temporary table same_claim_packet as select jsonb_set(jsonb_set(jsonb_set(p,'{partFour,retainedEvidence,fields}',jsonb_build_array((select f from science_fixture),(select f from same_claim_goal))),'{partFour,scientificDecision,assessments,1}',jsonb_build_object('goal','fine_lines','assessment',(select f->'value'->'assessment' from same_claim_goal))),'{findings,1}',jsonb_build_object('id','scientific:synthetic-original:fine_lines','scientificEvidence',jsonb_build_object('claimHash',repeat('b',64)))) p from goal_packet;
update same_claim_packet set p=jsonb_set(p,'{summary,affirmativePremiseIds}','["scientific:synthetic-original:oiliness","scientific:synthetic-original:fine_lines"]');
select ok(private.part_four_retained_evidence_valid(p->'partFour'->'retainedEvidence'),'same claim with independent goal dependencies meets whitelist') from same_claim_packet;
create temporary table same_claim_lost as select private.part_four_retained_packet(p,'display',now(),array['secondary-goal-context']) p from same_claim_packet;
select ok(exists(select 1 from jsonb_array_elements(p->'findings') q where q.value->>'id'='scientific:synthetic-original:oiliness'),'withdrawn goal cannot erase surviving same-claim finding') from same_claim_lost;
select ok(not exists(select 1 from jsonb_array_elements(p->'findings') q where q.value->>'id'='scientific:synthetic-original:fine_lines') and p->'partFour'->'scientificDecision'->'unresolvedGoals' ? 'fine_lines','exact withdrawn same-claim goal loses coverage') from same_claim_lost;
update private.part_four_scientific_authority set revoked=true where claim_id='synthetic-secondary';
create temporary table lost_goal as select private.part_four_retained_packet(p,'display',now()) p from goal_packet;
select is(p->'partFour'->'scientificDecision'->'assessments'->0->'assessment'->>'state','supported','unrelated primary scientific evidence survives') from lost_goal;
select is(p->'summary'->>'judgment','not_enough_info','lost last secondary support downgrades positive canonical summary') from lost_goal;
select ok(p->'partFour'->'scientificDecision'->'unresolvedGoals' ? 'fine_lines' and exists(select 1 from jsonb_array_elements(p->'materialGaps') q where q.value->>'reason'='goal_evidence'),'lost secondary goal becomes explicit unresolved gap') from lost_goal;
update private.part_four_scientific_authority set revoked=true where claim_id='synthetic-original';
select ok(not private.part_four_science_field_allowed(f,now()),'Revocation prevents replay') from science_fixture;
update private.part_four_scientific_authority set revoked=false where claim_id='synthetic-original';
insert into private.part_four_source_withdrawals(dependency_id) values('fixture-qualification');
select ok(not private.part_four_science_field_allowed(f,now()),'Qualification withdrawal blocks copied reference') from science_fixture;
update private.part_four_release set permitted=true;
create temporary table previous_release as select private.part_four_release_tuple(r) t from private.part_four_release r;
update private.part_four_release set release_hash=repeat('d',64),knowledge_hash=repeat('e',64),knowledge_version='synthetic-next';
select ok(private.part_four_saved_release_allowed(t),'Previously permitted tuple remains historical') from previous_release;
select ok(not private.part_four_saved_release_allowed(jsonb_set(t,'{knowledgeVersion}','"restamped"')),'Historical tuple must remain exact') from previous_release;
select ok(not private.part_four_saved_release_allowed(jsonb_set(t,'{releaseHash}',to_jsonb(repeat('f',64)))),'Unseen release cannot become historical') from previous_release;
insert into private.part_four_source_withdrawals(dependency_id) select t->>'releaseHash' from previous_release;
select ok(not private.part_four_saved_release_allowed(t),'Withdrawn historical release cannot replay') from previous_release;
select * from finish();
rollback;
